import { vi } from "vitest";
import { HTTPError, problem, type H3Event } from "../src/index.ts";
import { describeMatrix } from "./_setup.ts";

const PROBLEM_JSON = "application/problem+json";

describeMatrix("problem", (t, { it, expect, describe }) => {
  const consoleMock = ((globalThis.console.error as any) = vi.fn());

  describe("problem()", () => {
    it("returns an HTTPError with the given status and message", () => {
      const error = problem({ status: 404, message: "Usuário não encontrado" });
      expect(error).toBeInstanceOf(HTTPError);
      expect(HTTPError.isError(error)).toBe(true);
      expect(error.status).toBe(404);
      expect(error.message).toBe("Usuário não encontrado");
    });

    it("keeps type and instance out of the HTTPError fields", () => {
      const error = problem({
        status: 422,
        message: "Dados inválidos",
        type: "https://exemplo.com/erros/validacao",
        instance: "/pedidos/12",
      });
      expect(error).not.toHaveProperty("type");
      expect(error).not.toHaveProperty("instance");
      expect(Object.keys(error)).not.toContain("type");
      expect(Object.keys(error)).not.toContain("instance");
    });
  });

  describe("application/problem+json responses", () => {
    it("renders type, title, status, detail and instance", async () => {
      t.app.use(() => {
        throw problem({
          status: 404,
          statusText: "Not Found",
          message: "Usuário não encontrado",
          instance: "/usuarios/7",
        });
      });

      const res = await t.fetch("/");
      expect(res.status).toBe(404);
      expect(res.headers.get("content-type")).toBe(PROBLEM_JSON);
      expect(await res.json()).toEqual({
        type: "about:blank",
        title: "Not Found",
        status: 404,
        detail: "Usuário não encontrado",
        instance: "/usuarios/7",
      });
    });

    it("uses the IANA phrase as title when statusText is missing", async () => {
      t.app.use(() => {
        throw problem({ status: 404, message: "Not here" });
      });

      const body = await (await t.fetch("/")).json();
      expect(body.title).toBe("Not Found");
    });

    it("uses the IANA phrase for a status with a newer name", async () => {
      t.app.use(() => {
        throw problem({ status: 422, message: "Dados inválidos" });
      });

      const body = await (await t.fetch("/")).json();
      expect(body.title).toBe("Unprocessable Content");
    });

    it("uses HTTPError as title when the status has no registered phrase", async () => {
      t.app.use(() => {
        throw problem({ status: 599, message: "Custom" });
      });

      const res = await t.fetch("/");
      expect(res.status).toBe(599);
      expect((await res.json()).title).toBe("HTTPError");
    });

    it("uses about:blank as type when type is missing", async () => {
      t.app.use(() => {
        throw problem({ status: 400, message: "Bad" });
      });

      const body = await (await t.fetch("/")).json();
      expect(body.type).toBe("about:blank");
    });

    it("uses the given type", async () => {
      t.app.use(() => {
        throw problem({
          status: 422,
          message: "Dados inválidos",
          type: "https://exemplo.com/erros/validacao",
        });
      });

      const body = await (await t.fetch("/")).json();
      expect(body.type).toBe("https://exemplo.com/erros/validacao");
    });

    it("omits instance when it is not given", async () => {
      t.app.use(() => {
        throw problem({ status: 400, message: "Bad" });
      });

      const body = await (await t.fetch("/")).json();
      expect(body).not.toHaveProperty("instance");
    });

    it("keeps the message as detail and not as a top-level message", async () => {
      t.app.use(() => {
        throw problem({ status: 400, message: "Bad" });
      });

      const body = await (await t.fetch("/")).json();
      expect(body.detail).toBe("Bad");
      expect(body).not.toHaveProperty("message");
    });

    it("puts body members at the top level and data under data", async () => {
      t.app.use(() => {
        throw problem({
          status: 409,
          message: "Conflito",
          data: { campo: "email" },
          body: { codigo: "X1" },
        });
      });

      const res = await t.fetch("/");
      expect(res.status).toBe(409);
      const body = await res.json();
      expect(body.codigo).toBe("X1");
      expect(body.data).toEqual({ campo: "email" });
      expect(body.status).toBe(409);
    });

    it("does not let body members override reserved members", async () => {
      t.app.use(() => {
        throw problem({
          status: 404,
          message: "Não encontrado",
          body: {
            status: 200,
            title: "x",
            type: "https://evil.example/",
            detail: "outro",
            instance: "/injetado",
            codigo: "X1",
          },
        });
      });

      const res = await t.fetch("/");
      expect(res.status).toBe(404);
      const body = await res.json();
      expect(body.status).toBe(404);
      expect(body.title).toBe("Not Found");
      expect(body.type).toBe("about:blank");
      expect(body.detail).toBe("Não encontrado");
      expect(body).not.toHaveProperty("instance");
      expect(body.codigo).toBe("X1");
    });

    it("hides data, body, message and instance for unhandled errors", async () => {
      // `stack` (debug only) starts with the message, as it does for the common format
      t.app.config.debug = false;
      t.app.use(() => {
        throw problem({
          status: 500,
          message: "senha do banco vazou",
          data: { sql: "SELECT password FROM users" },
          body: { codigo: "X1" },
          instance: "/interno/42",
          unhandled: true,
        });
      });

      const res = await t.fetch("/");
      expect(res.status).toBe(500);
      expect(res.headers.get("content-type")).toBe(PROBLEM_JSON);
      const text = await res.text();
      expect(text).not.toContain("senha");
      expect(text).not.toContain("SELECT");
      const body = JSON.parse(text);
      expect(body.detail).toBe("HTTPError");
      expect(body.status).toBe(500);
      expect(body).not.toHaveProperty("data");
      expect(body).not.toHaveProperty("codigo");
      expect(body).not.toHaveProperty("instance");
      t.errors = [];
    });

    it("applies error headers", async () => {
      t.app.use(() => {
        throw problem({
          status: 401,
          message: "Não autenticado",
          headers: { "WWW-Authenticate": "Bearer" },
        });
      });

      const res = await t.fetch("/");
      expect(res.status).toBe(401);
      expect(res.headers.get("www-authenticate")).toBe("Bearer");
      expect(res.headers.get("content-type")).toBe(PROBLEM_JSON);
    });

    it("forces content-type even when headers sets another one", async () => {
      t.app.use(() => {
        throw problem({
          status: 401,
          message: "Não autenticado",
          headers: { "WWW-Authenticate": "Bearer", "Content-Type": "text/plain" },
        });
      });

      const res = await t.fetch("/");
      expect(res.headers.get("www-authenticate")).toBe("Bearer");
      expect(res.headers.get("content-type")).toBe(PROBLEM_JSON);
    });

    it("forces content-type even when event.res.errHeaders sets another one", async () => {
      t.app.use((event: H3Event) => {
        event.res.errHeaders.set("content-type", "text/plain");
        event.res.errHeaders.set("x-error", "prepared");
        throw problem({ status: 400, message: "Bad" });
      });

      const res = await t.fetch("/");
      expect(res.headers.get("x-error")).toBe("prepared");
      expect(res.headers.get("content-type")).toBe(PROBLEM_JSON);
    });

    it("accumulates set-cookie from headers and errHeaders", async () => {
      t.app.use((event: H3Event) => {
        event.res.errHeaders.append("set-cookie", "prepared=1");
        throw problem({
          status: 400,
          message: "Bad",
          headers: { "set-cookie": "error=1" },
        });
      });

      const res = await t.fetch("/");
      expect(res.headers.get("content-type")).toBe(PROBLEM_JSON);
      expect(res.headers.getSetCookie()).toEqual(["error=1", "prepared=1"]);
    });

    it("includes stack in debug mode", async () => {
      t.app.use(() => {
        throw problem({ status: 400, message: "Bad" });
      });

      const body = await (await t.fetch("/")).json();
      expect(Array.isArray(body.stack)).toBe(true);
      expect(body.stack.length).toBeGreaterThan(0);
    });

    it("omits stack when debug is off", async () => {
      t.app.config.debug = false;
      t.app.use(() => {
        throw problem({ status: 400, message: "Bad" });
      });

      const body = await (await t.fetch("/")).json();
      expect(body).not.toHaveProperty("stack");
    });

    it("sends an empty body for HEAD requests", async () => {
      t.app.use(() => {
        throw problem({ status: 404, message: "Não encontrado" });
      });

      const res = await t.fetch("/", { method: "HEAD" });
      expect(res.status).toBe(404);
      expect(res.headers.get("content-type")).toBe(PROBLEM_JSON);
      expect(await res.text()).toBe("");
    });
  });

  describe("onError", () => {
    it("receives the problem error unchanged", async () => {
      t.app.use(() => {
        throw problem({ status: 404, message: "Não encontrado" });
      });

      await t.fetch("/");
      expect(t.hooks.onError).toHaveBeenCalledTimes(1);
      const received = t.hooks.onError.mock.calls[0]![0] as HTTPError;
      expect(HTTPError.isError(received)).toBe(true);
      expect(received.status).toBe(404);
      expect(received.message).toBe("Não encontrado");
    });

    it("keeps problem+json when the hook returns undefined", async () => {
      t.app.use(() => {
        throw problem({ status: 404, message: "Não encontrado" });
      });

      const res = await t.fetch("/");
      expect(res.headers.get("content-type")).toBe(PROBLEM_JSON);
      expect((await res.json()).detail).toBe("Não encontrado");
    });

    it("uses the Response returned by the hook", async () => {
      t.app.config.onError = () => new Response("custom", { status: 503 });
      t.app.use(() => {
        throw problem({ status: 404, message: "Não encontrado" });
      });

      const res = await t.fetch("/");
      expect(res.status).toBe(503);
      expect(res.headers.get("content-type")).not.toBe(PROBLEM_JSON);
      expect(await res.text()).toBe("custom");
    });
  });

  describe("common errors keep the existing format", () => {
    it("HTTPError.status() is not rendered as problem+json", async () => {
      t.app.use(() => {
        throw HTTPError.status(404, "Not Found", {
          message: "Não encontrado",
          data: { id: 7 },
        });
      });

      const res = await t.fetch("/");
      expect(res.status).toBe(404);
      expect(res.headers.get("content-type")).not.toBe(PROBLEM_JSON);
      const body = await res.json();
      expect(body.status).toBe(404);
      expect(body.statusText).toBe("Not Found");
      expect(body.message).toBe("Não encontrado");
      expect(body.data).toEqual({ id: 7 });
      expect(body).not.toHaveProperty("type");
    });

    it("a problem passed as cause does not change the format", async () => {
      t.app.use(() => {
        throw new HTTPError({
          cause: problem({ status: 418, message: "inner" }),
        });
      });

      const res = await t.fetch("/");
      expect(res.status).toBe(418);
      expect(res.headers.get("content-type")).not.toBe(PROBLEM_JSON);
      const body = await res.json();
      expect(body).not.toHaveProperty("type");
      expect(body.message).toBe("inner");
    });
  });
});

